"use strict";exports.id=31134,exports.ids=[31134],exports.modules={31134:a=>{a.exports=JSON.parse('{"_status":"machine-draft, needs human review","Based on your answers, we are connecting you with immediate support. Please reach out for support now. This information is free and always available — no payment, no registration required.":"ብመሰረት መልስታትኩም፡ ምስ ቅልጡፍ ደገፍ ነራኽበኩም ኣለና። በጃኹም ሕጂ ደገፍ ሕተቱ። እዚ ሓበሬታ እዚ ብናጻን ኩሉ ግዜ ዝርከብን እዩ — ክፍሊት ወይ ምዝገባ ኣየድልን።","Belonging & Community":"ኣባልነትን ማሕበረሰብን","Biological, Wellbeing and Health":"ባዮሎጂ፣ ደሓንነትን ጥዕናን","If you are in immediate danger, contact local emergency services or go to the nearest health facility now.":"ኣብ ቅልጡፍ ሓደጋ እንተሎኹም፡ ናይ ከባቢኹም ህጹጽ ኣገልግሎት ተወከሱ ወይ ሕጂ ናብ ዝቐረበ ትካል ጥዕና ኺዱ።","If you are struggling to meet your basic needs, these services can help. This information is free and always available.":"መሰረታዊ ድሌታትኩም ንምምላእ እንተ ተሸጊርኩም፡ እዞም ኣገልግሎታት ክሕግዙኹም ይኽእሉ። እዚ ሓበሬታ እዚ ብናጻን ኩሉ ግዜ ዝርከብን እዩ።","Money & Business Reflection":"ኣስተንትኖ ገንዘብን ንግድን","Peace & Harmony":"ሰላምን ስምምዕን","Relationships & Family":"ዝምድናታትን ስድራን","Spiritual & Life Direction":"መንፈሳውን ኣንፈት ህይወትን","being reviewed":"ይግምገም ኣሎ","consultation requested":"ምኽሪ ተሓቲቱ","full report available":"ምሉእ ጸብጻብ ይርከብ","high":"ልዑል","not submitted yet":"ገና ኣይተላእከን","referral advised":"ሪፈራል ተመኺሩ","report ready":"ጸብጻብ ተዳልዩ","support contacts shared":"ናይ ደገፍ ኣድራሻታት ተዋሂቦም","urgent":"ህጹጽ","waiting for a reviewer":"ገምጋሚ ይጽበ ኣሎ"}')}};